// Recovery payload for a 404. A real 404 status is only half the contract an
// agent needs: the other half is being told where to look next, in the media
// type it asked for. Every representation of a not-found response (Markdown,
// JSON, HTML) is built from the ONE list below, so the three can never drift.
//
// Why this exists: the Is Agentic audit scored "agent-friendly 404s" at 50%:
// "Nonexistent paths return a real HTTP 404. For full credit, include a short
// markdown body (site map links, where to look next) so agents can recover."

export type RecoveryLink = {
	href: string;
	title: string;
	desc: string;
};

/** Where an agent that hit a dead end should go next, most useful first. */
export const RECOVERY_LINKS: readonly RecoveryLink[] = [
	{
		href: "/llms.txt",
		title: "llms.txt",
		desc: "Machine-readable site index: what this site is, its use cases, and every resource URL.",
	},
	{
		href: "/docs/foundations/overview",
		title: "Documentation",
		desc: "Human- and agent-readable docs. Append .md to any docs URL for raw Markdown.",
	},
	{
		href: "/docs/llms.txt",
		title: "Full page index",
		desc: "Every documentation page, one line each, the fastest way to find a moved page.",
	},
	{
		href: "/sitemap.xml",
		title: "Sitemap",
		desc: "XML sitemap of every indexable URL on this origin.",
	},
	{
		href: "/.well-known/api-catalog",
		title: "API catalog (RFC 9727)",
		desc: "Linkset of every discoverable API surface.",
	},
	{
		href: "/openapi.json",
		title: "OpenAPI 3.1 spec",
		desc: "The full REST surface, for function-calling and client generation.",
	},
	{
		href: "/api/search?query=",
		title: "Search API",
		desc: "GET /api/search?query=..., find the page you were looking for by keyword.",
	},
	{
		href: "/developers",
		title: "Developer resources",
		desc: "Index of every developer-facing surface (docs, spec, MCP, packages, policies).",
	},
];

/**
 * Short Markdown body for a 404. Deliberately compact, an agent recovering
 * from a dead link needs the next hop, not a page of prose.
 */
export function notFoundMarkdown(pathname: string, origin: string): string {
	return [
		"# 404: Not found",
		"",
		`No resource exists at \`${pathname}\` on ${origin}.`,
		"",
		"## Where to look next",
		"",
		...RECOVERY_LINKS.map((l) => `- [${l.title}](${l.href}): ${l.desc}`),
		"",
		"## Notes for agents",
		"",
		"- This is a genuine `404`. This origin never answers an unknown path with `200`, so a `404` here means the path does not exist, not that it is temporarily unavailable.",
		"- Send `Accept: application/json` for the same error as an RFC 9457 Problem Details object.",
		"- Send `Accept: text/markdown`, or append `.md`, to read any documentation page as raw Markdown.",
		"",
	].join("\n");
}

/**
 * The same recovery links as RFC 9457 extension members. Extension members are
 * explicitly permitted by RFC 9457 §3.2, so this stays a valid problem object
 * while carrying the recovery hop a bare `detail` string cannot.
 */
export function notFoundExtensions(origin: string) {
	return {
		links: RECOVERY_LINKS.map((l) => ({
			href: `${origin}${l.href}`,
			title: l.title,
			description: l.desc,
		})),
		// A Markdown rendering of the same recovery guidance, so a client that
		// only ever parses JSON still gets the prose without a second request.
		markdown: RECOVERY_LINKS.map((l) => `- [${l.title}](${l.href}): ${l.desc}`).join("\n"),
	};
}
